// from src/locales/de/blog.ts. Body + FAQs for article 'how-to-remove-background-from-image' (de).
// This file is the single source for this article's de body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Den Hintergrund aus einem Foto zu entfernen, dauert weniger als eine Minute, wenn man die Schritte kennt. Wählen Sie ein gutes Foto, laden Sie es hoch, prüfen Sie den Ausschnitt und laden Sie ihn herunter.</p>\n<p>Diese Anleitung führt Sie durch den gesamten Ablauf im <a href=\"/de/hintergrund-entfernen/\">KI-Hintergrundentferner</a> von CompressMyPic – vom ersten Laden des Modells bis zur fertigen Datei. Sie behandelt auch die Probleme, die am häufigsten auftreten, und wie Sie sie beheben.</p>\n<p>Designkenntnisse sind nicht nötig. Wer eine Datei in ein Browserfenster ziehen kann, kann auch einen Hintergrund entfernen.</p>\n<p>Ihr Foto verlässt Ihr Gerät nie. Der gesamte Ablauf läuft in Ihrem Browser, sodass private Fotos von Anfang bis Ende privat bleiben.</p>\n<h2 id=\"pick-the-right-photo\">Vor dem Start: Das richtige Foto wählen</h2>\n<p>Ein gutes Ergebnis beginnt schon vor dem Hochladen. Das Foto, das Sie wählen, entscheidet über den größten Teil der Qualität – nehmen Sie sich also eine Minute Zeit für die richtige Auswahl.</p>\n<p>Wählen Sie ein Foto, in dem das Motiv klar zu erkennen ist und einen guten Teil des Bildes ausfüllt. Eine Person, ein Produkt oder ein Haustier, das sich vom Hintergrund abhebt, macht es der KI leicht.</p>\n<p>Bevorzugen Sie einen einfachen Hintergrund. Eine schlichte Wand, ein Tisch oder ein offener Himmel lassen sich sauber trennen, während ein volles Zimmer oder ein gemusterter Hintergrund die KI raten lässt.</p>\n<p>Achten Sie auf das Licht. Weiches, gleichmäßiges Licht auf dem Motiv und ein wenig Kontrast zum Hintergrund helfen dem Modell, die Kontur zu finden. Harte Schatten hinter dem Motiv sorgen später für Probleme.</p>\n<p>Wenn das Foto breiter ist als nötig, schneiden Sie es zuerst zu. Die Funktion <a href=\"/de/bild-zuschneiden/\">„Bild zuschneiden“</a> entfernt die überflüssige Umgebung, und ein engerer Bildausschnitt ergibt meist einen saubereren Ausschnitt.</p>\n<h2 id=\"step-1-model-load\">Schritt 1: Warten, bis das KI-Modell geladen ist</h2>\n<p>Öffnen Sie die Seite des <a href=\"/de/hintergrund-entfernen/\">KI-Hintergrundentferners</a>. Bei Ihrem ersten Besuch lädt die Seite ein kompaktes KI-Modell von etwa 35 MB herunter, bevor das Werkzeug bereit ist.</p>\n<p>Der Download dauert bei einer schnellen Verbindung wenige Sekunden, bei langsamem WLAN länger. Warten Sie, bis die Seite meldet, dass das Modell bereit ist, bevor Sie ein Foto hochladen.</p>\n<p>Dieser Download passiert nur einmal. Das Modell wird in Ihrem Browser zwischengespeichert, sodass spätere Besuche ohne jede Wartezeit sofort starten.</p>\n<p>Wenn Sie mobile Daten nutzen, verwenden Sie für den ersten Besuch WLAN. Der 35-MB-Download des Modells ist die einzige große Übertragung – alles danach ist klein.</p>\n<h2 id=\"step-2-upload\">Schritt 2: Ihr Foto hochladen</h2>\n<p>Ziehen Sie Ihr Foto in den Upload-Bereich oder klicken Sie darauf, um eine Datei von Ihrem Gerät auszuwählen. Das Werkzeug akzeptiert JPG-, PNG-, WebP-, HEIC-, BMP- und AVIF-Dateien bis zu 20 MB.</p>\n<p>Laden Sie jeweils ein Foto hoch. Das Werkzeug verarbeitet ein einzelnes Foto, damit das KI-Modell den gesamten Gerätespeicher auf einen sauberen Ausschnitt konzentrieren kann.</p>\n<p>HEIC-Fotos von iPhones funktionieren direkt. Das Werkzeug wandelt sie automatisch in ein lesbares Bild um, sodass Sie sie vorher nicht umwandeln müssen.</p>\n<p>Große Fotos brauchen etwas länger, weil die KI auf Ihrem Gerät läuft. Eine 20-MB-Aufnahme von der Kamera braucht mehr Rechenzeit als ein kleines Handyfoto – haben Sie also ein paar Sekunden Geduld.</p>\n<p>Bewahren Sie die Originaldatei sicher auf. Das Werkzeug verändert Ihr Ausgangsfoto nie, sodass Sie es jederzeit erneut hochladen oder für eine andere Bearbeitung verwenden können.</p>\n<h2 id=\"step-3-ai-cutout\">Schritt 3: Die KI schneidet das Motiv frei</h2>\n<p>Sobald das Foto hochgeladen ist, scannt die KI es und erstellt eine Maske, die jeden Pixel als Motiv oder Hintergrund markiert. Das dauert meist nur wenige Sekunden.</p>\n<p>Sie müssen nichts zeichnen und das Motiv auch nicht selbst markieren. Das Modell hat gelernt, wie Menschen, Produkte und Tiere aussehen, und findet die Kontur deshalb von allein.</p>\n<p>Wenn es fertig ist, zeigt die Seite Ihr Originalfoto neben dem transparenten Ausschnitt. Das Motiv bleibt unberührt, und der Hintergrund wird zu leerem Raum.</p>\n<p>Wenn der erste Durchlauf einen Schatten als Teil des Motivs mitnimmt, nutzen Sie „Erneut entfernen“. Das Modell liefert bei demselben Foto immer dasselbe Ergebnis – ändern Sie also lieber das Foto selbst, etwa durch engeres Zuschneiden oder einen schlichteren Hintergrund, und laden Sie es erneut hoch.</p>\n<h2 id=\"step-4-split-compare\">Schritt 4: Den Ausschnitt im Vorher-Nachher-Vergleich prüfen</h2>\n<p>Prüfen Sie den Ausschnitt vor dem Herunterladen sorgfältig. Klicken Sie auf „Geteilter Vergleich“, um über die Ansicht zu wischen und genau zu sehen, was behalten und was entfernt wurde.</p>\n<p>Schauen Sie sich zuerst die Kanten an. Haare, Fell, Ohren, Griffe, Riemen und dünne Teile sind die Stellen, an denen Fehler sichtbar werden – zoomen Sie also hinein und prüfen Sie sie genau.</p>\n<p>Achten Sie auf Hintergrundreste an Ecken und Kanten. Ein kleiner Fleck des alten Hintergrunds kann an einer komplexen Kontur überleben und fällt in kleiner Ansicht kaum auf.</p>\n<p>Prüfen Sie auch, ob Teile fehlen. Ein gleichfarbiger Ärmel, ein Glasteil oder ein dünnes Kabel kann mit dem Hintergrund weggeschnitten werden und eine Lücke im Motiv hinterlassen.</p>\n<p>Wenn das Ergebnis nicht sauber ist, hilft kein Herumprobieren. Versuchen Sie es mit einem Foto mit stärkerem Kontrast, schneiden Sie näher am Motiv zu oder fotografieren Sie mit einem schlichteren Hintergrund neu und laden Sie das Bild erneut hoch.</p>\n<p>Achten Sie besonders auf Hände, Füße und alles, was das Motiv in der Hand hält. Kleine Gegenstände nahe am Bildrand werden leicht versehentlich weggeschnitten, und die Vergleichsansicht zeigt sie deutlich.</p>\n<h2 id=\"step-5-choose-background\">Schritt 5: Transparent oder einfarbiger Hintergrund?</h2>\n<p>Wenn der Ausschnitt gut aussieht, wählen Sie, wie Sie ihn exportieren. Transparent lässt den Hintergrund leer, sodass der Ausschnitt auf jeder Farbe und jedem Design dahinter funktioniert.</p>\n<p>Wählen Sie transparent, wenn der Ausschnitt in ein Designprogramm wandert. Canva, Photoshop, Figma, PowerPoint und Google Slides akzeptieren alle transparente PNGs, und der Ausschnitt fügt sich in jede Folie und jedes Layout ein.</p>\n<p>Wählen Sie Weiß, wenn das Bild für eine Marktplatz-Anzeige bestimmt ist. Amazon und eBay bevorzugen klare Bilder mit weißem Hintergrund für die Hauptbilder von Produkten, und der weiße Export entspricht genau dieser Regel.</p>\n<p>Wählen Sie Schwarz für einen dramatischen Effekt oder eine eigene Farbe passend zu Ihrer Marke. Bei einer eigenen Farbe können Sie jeden Hex-Wert eingeben, sodass der Hintergrund exakt zu Ihrer Website oder Verpackung passen kann.</p>\n<p>Denken Sie daran, dass ein transparentes PNG größer ist als ein JPG desselben Bildes. PNG speichert jeden Pixel verlustfrei, sodass ein großer, detailreicher Ausschnitt schwerer sein kann als das Originalfoto.</p>\n<h2 id=\"step-6-download\">Schritt 6: Ihren Ausschnitt herunterladen</h2>\n<p>Klicken Sie auf „Herunterladen“ für die Version, die Sie gewählt haben. Das transparente PNG trägt den Namen Ihres Fotos mit dem Zusatz _no_bg, sodass Sie es später leicht wiederfinden.</p>\n<p>Das heruntergeladene Bild behält die ursprüngliche Auflösung. Ein Produktfoto mit 4000 Pixeln bleibt 4000 Pixel breit, sodass der Ausschnitt auch für den Druck scharf genug ist – nicht nur fürs Web.</p>\n<p>Klicken Sie nach dem Herunterladen auf „Neues Bild“, um das nächste Foto zu bearbeiten. Es gibt kein Tageslimit, sodass Sie eine ganze Fotoserie nacheinander durcharbeiten können.</p>\n<p>Speichern Sie das transparente PNG als Ihre Ausgangsdatei. Daraus können Sie später Versionen mit weißem Hintergrund, in anderer Größe oder komprimiert erstellen, ohne den Hintergrund erneut entfernen zu müssen.</p>\n<h2 id=\"fixing-common-problems\">Häufige Probleme beheben</h2>\n<p>Ein schwacher Lichthof um das Motiv ist der häufigste Fehler. Er entsteht, wenn die Kante zwischen Motiv und Hintergrund weich ist und das Modell einen dünnen Ring des alten Hintergrunds behält.</p>\n<p>Einem Lichthof beugt man leichter vor, als ihn zu beheben. Fotografieren Sie mit einem schlichten Hintergrund, der sich vom Motiv abhebt, neu – dann wird die Kante deutlich sauberer.</p>\n<p>Wenn ein Teil des Motivs fehlt, verschwimmt das Motiv wahrscheinlich mit dem Hintergrund. Gleichfarbige Kleidung, Glas oder Tarnmuster verwirren das Modell – wechseln Sie also den Hintergrund und versuchen Sie es erneut.</p>\n<p>Wenn der Hintergrund unruhig ist, können die Kanten rau aussehen. Schneiden Sie das Foto vor dem Hochladen näher am Motiv zu – das entfernt Ablenkungen und gibt dem Modell weniger, worüber es raten muss.</p>\n<p>Wenn der Ausschnitt in kleiner Ansicht gut aussieht, beim Hineinzoomen aber rau wirkt, ist das Foto selbst möglicherweise zu niedrig aufgelöst. Beginnen Sie mit dem hochwertigsten Original, das Sie haben, nicht mit einer komprimierten Kopie.</p>\n<p>Wenn ein Schatten als dunkler Fleck unter dem Motiv überlebt, war er im Originalfoto wahrscheinlich stark. Fotografieren Sie mit weicherem, gleichmäßigem Licht neu, dann verschwindet der Schatten meist aus dem Ausschnitt.</p>\n<h2 id=\"product-photo-workflow\">Produktfotos freistellen, Schritt für Schritt</h2>\n<p>Bei Produktfotos gelten dieselben Schritte, mit ein paar zusätzlichen Prüfungen. Ein Anzeigenbild wird auf den ersten Blick beurteilt, deshalb sind Kanten und Hintergrundfarbe hier wichtiger als überall sonst.</p>\n<p>Fotografieren Sie das Produkt vor dem Start auf einer schlichten Fläche in weichem Tageslicht. Ein weißes Tuch, ein schlichter Tisch oder eine helle Wand geben der KI einen einfachen Hintergrund zum Entfernen.</p>\n<p>Laden Sie das Foto hoch und prüfen Sie den Ausschnitt in voller Größe. Zoomen Sie in Ecken, Griffe, Riemen und Kabel hinein, wo sich Hintergrundreste am häufigsten verstecken.</p>\n<p>Exportieren Sie auf Weiß für das Hauptbild der Anzeige. Marktplätze erwarten einen rein weißen Hintergrund, und der weiße Export aus dem Werkzeug erfüllt diese Anforderung direkt.</p>\n<p>Behalten Sie auch das transparente PNG. Derselbe Ausschnitt kann auf ein farbiges Banner, in einen Social-Media-Beitrag oder auf Ihre eigene Shopseite wandern, wo ein weißer Kasten fehl am Platz wäre.</p>\n<p>Arbeiten Sie eine Serie Foto für Foto durch. Es gibt kein Tageslimit, sodass Sie den Hintergrund aus einer ganzen Produktpalette in einer Sitzung entfernen können.</p>\n<h2 id=\"portrait-workflow\">Porträts freistellen</h2>\n<p>Porträts brauchen rund um die Haare besondere Sorgfalt. Lose Strähnen, Locken und abstehende Haare verwischen die Grenze zwischen Person und Hintergrund, und ein kompaktes Modell kann sie aufweichen.</p>\n<p>Bitten Sie die Person, sich vor eine schlichte Wand oder einen Vorhang zu stellen. Eine klare Kontrastlinie um Kopf und Schultern gibt dem Modell die einfachste Kontur, der es folgen kann.</p>\n<p>Leuchten Sie das Gesicht gut aus und halten Sie den Hintergrund nach Möglichkeit etwas dunkler. Ein gut ausgeleuchtetes Motiv vor einem dunkleren Hintergrund lässt sich sauberer trennen als ein dunkles Motiv in einem hellen Raum.</p>\n<p>Nutzen Sie nach dem Entfernen den Vorher-Nachher-Vergleich und schauen Sie sich Haaransatz, Ohren und Schultern genau an. Ein kleiner Fehler dort fällt in voller Größe sofort ins Auge.</p>\n<p>Legen Sie das fertige Porträt auf einen Hintergrund, der zu seinem Zweck passt. Ein neutrales Grau oder eine sanfte Farbe eignet sich für ein professionelles Profil, eine kräftige Farbe für ein Social-Media-Vorschaubild.</p>\n<h2 id=\"removing-background-on-phone\">Hintergrund auf dem Handy entfernen</h2>\n<p>Das Werkzeug funktioniert auch in mobilen Browsern. Es läuft in Safari auf iOS und in Chrome auf Android, mit denselben Upload-, Vergleichs- und Download-Funktionen.</p>\n<p>Nutzen Sie für den ersten Besuch WLAN, damit die 35 MB des Modells schnell heruntergeladen werden. Danach ist das Modell zwischengespeichert, und die Entfernung selbst läuft auf dem Handy.</p>\n<p>Große Fotos brauchen auf dem Handy länger, weil die KI auf dem Handyprozessor läuft. Eine hochauflösende Kameraaufnahme kann im Vergleich zum Laptop ein paar Sekunden mehr brauchen.</p>\n<p>Der Download funktioniert genauso. Das PNG wird in Ihrer Fotos- oder Dateien-App gespeichert und ist bereit zum Teilen oder zum Öffnen in einer Design-App auf dem Handy.</p>\n<h2 id=\"what-to-do-next\">Was Sie mit Ihrem Ausschnitt als Nächstes tun</h2>\n<p>Ein Ausschnitt ist selten das endgültige Bild. Die meisten Menschen legen ihn auf einen neuen Hintergrund, ändern seine Größe oder komprimieren ihn vor der Veröffentlichung – und für jeden Schritt gibt es ein Werkzeug.</p>\n<p>Das Werkzeug <a href=\"/de/hintergrund-zu-bild-hinzufuegen/\">Hintergrund zum Bild hinzufügen</a> setzt Ihren Ausschnitt auf eine Farbe, einen Verlauf oder ein anderes Foto. Es ist der natürliche nächste Schritt nach dem Entfernen.</p>\n<p>Die Funktion <a href=\"/de/bild-zuschneiden/\">„Bild zuschneiden“</a> schneidet den Ausschnitt auf die genaue Form zu, die Sie brauchen – etwa ein Quadrat für ein Profilbild oder ein breites Format für ein Banner.</p>\n<p>Die Funktion <a href=\"/de/bilder-konvertieren/\">„Bilder konvertieren“</a> ändert das Format. Aus einem transparenten PNG wird ein WebP für schnellere Webseiten, oder aus einer Version mit weißem Hintergrund ein JPG für eine Anzeige.</p>\n<p>Wenn das PNG zu groß für Ihre Seite ist, komprimieren Sie es danach. Der Hauptkompressor auf der <a href=\"/de/\">CompressMyPic-Startseite</a> verkleinert Bilder, ohne sie unscharf zu machen.</p>\n<p>Speichern Sie den transparenten Ausschnitt in einem Ordner mit Ihren anderen Design-Dateien. Dieselbe Datei kann eine Anzeige, einen Social-Media-Beitrag und eine Präsentation bedienen – Sie entfernen den Hintergrund also nur einmal.</p>\n<h2 id=\"how-to-remove-background-summary\">Kurze Checkliste</h2>\n<p>Wählen Sie ein Foto mit klarem Motiv, einfachem Hintergrund und gutem Licht. Schneiden Sie es näher am Motiv zu, wenn die Szene unruhig ist.</p>\n<p>Öffnen Sie den <a href=\"/de/hintergrund-entfernen/\">KI-Hintergrundentferner</a>, warten Sie beim ersten Besuch, bis das Modell geladen ist, und laden Sie dann ein Foto von bis zu 20 MB hoch.</p>\n<p>Prüfen Sie den Ausschnitt im Vorher-Nachher-Vergleich, wählen Sie transparent oder einen einfarbigen Hintergrund und laden Sie das PNG herunter. Speichern Sie die transparente Version als Ihre Ausgangsdatei.</p>\n<p>Die vollständigen Hintergründe zur Funktionsweise des Werkzeugs finden Sie unter <a href=\"/de/blog/hintergrund-entfernen-anleitung/\">Hintergrund entfernen: Die komplette Anleitung</a>. Ob KI oder manuelle Bearbeitung besser zu einer Aufgabe passt, erfahren Sie unter <a href=\"/de/blog/ki-hintergrundentfernung-vs-manuelles-freistellen/\">Hintergrund mit KI entfernen oder manuell freistellen? Der Vergleich</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Sollte ich mein Foto vor dem Entfernen des Hintergrunds zuschneiden?","answer":"Ja, wenn die Szene unruhig ist. Wer näher am Motiv zuschneidet, entfernt Ablenkungen und gibt der KI weniger Hintergrund, den sie mit dem Motiv verwechseln könnte – das ergibt meist eine sauberere Kante. Nutzen Sie zuerst die Funktion „Bild zuschneiden“ und laden Sie dann das zugeschnittene Foto hoch. Wenn das Foto bereits einen schlichten Hintergrund hat, ist das Zuschneiden optional."},{"question":"Kann ich die Hintergrundfarbe nach dem Herunterladen des Ausschnitts noch ändern?","answer":"Nur wenn Sie das transparente PNG heruntergeladen haben. Einen transparenten Ausschnitt können Sie später auf jede beliebige Farbe legen – in jeder Design-App oder mit dem Werkzeug „Hintergrund zum Bild hinzufügen“. Wenn Sie die Version mit weißem Hintergrund heruntergeladen haben, ist das Weiß fest im Bild und lässt sich nicht mehr entfernen. Bewahren Sie also das transparente PNG immer als Ausgangsdatei auf."},{"question":"Warum hat mein Ausschnitt einen schwachen Lichthof an den Kanten?","answer":"Ein Lichthof ist ein dünner Ring des alten Hintergrunds, der überlebt, weil die Kante zwischen Motiv und Hintergrund weich ist. Das passiert am häufigsten bei unscharfen Kanten, geringem Kontrast oder unruhiger Umgebung. Beugen Sie ihm vor, indem Sie mit einem schlichten Hintergrund neu fotografieren, der sich vom Motiv abhebt – ein dunkles Motiv vor einer hellen Wand zum Beispiel –, dann wird die Kante deutlich sauberer."},{"question":"Kann ich den Hintergrund aus einem Logo entfernen, das auf weißem Hintergrund steht?","answer":"Ja, und Logos gehören zu den einfachsten Fällen, weil ihre Konturen scharf sind und der Hintergrund schlicht ist. Laden Sie das Logo hoch, prüfen Sie den Ausschnitt und laden Sie das transparente PNG herunter. Das Ergebnis sitzt sauber in der Kopfzeile einer Website, auf einer Visitenkarte oder auf einer Folie, ohne dass ein weißer Kasten darum erscheint."},{"question":"Wie füge ich nach dem Entfernen einen neuen Hintergrund hinzu?","answer":"Laden Sie zuerst das transparente PNG herunter und öffnen Sie dann das Werkzeug „Hintergrund zum Bild hinzufügen“, um den Ausschnitt hochzuladen. Sie können ihn auf eine einfarbige Farbe, einen Verlauf oder ein anderes Foto legen und das fertige Bild exportieren. Wenn Sie Entfernen und Hintergrundwechsel als zwei getrennte Schritte halten, können Sie denselben Ausschnitt auch für andere Designs wiederverwenden."},{"question":"Wie groß sollte mein Foto für das beste Ergebnis sein?","answer":"Nutzen Sie das hochwertigste Original, das Sie haben, bis zur Grenze von 20 MB. Ein scharfes, hochauflösendes Foto gibt dem Modell eine klare Kante, der es folgen kann, während eine kleine oder stark komprimierte Kopie die Kontur verwischt und einen raueren Ausschnitt ergibt. Das Werkzeug behält die ursprüngliche Auflösung im Download, sodass es nichts kostet, groß anzufangen."}];
